/* ===== Injected: centered search box in the top bar (all pages) ===== */
(function(){
  function build(){
    var inner=document.querySelector('.nav-inner');
    if(!inner||inner.querySelector('.nav-search'))return;
    var brand=inner.querySelector('.brand');
    var isAr=document.documentElement.getAttribute('data-lang')==='ar';
    var f=document.createElement('form');
    f.className='nav-search';f.setAttribute('role','search');
    f.action='search.html';f.method='get';
    var i=document.createElement('input');
    i.type='search';i.name='q';
    i.placeholder=isAr?'ابحث في الكورسات…':'Search courses…';
    i.setAttribute('data-ar-ph','ابحث في الكورسات…');
    i.setAttribute('aria-label',isAr?'بحث':'Search');
    var b=document.createElement('button');
    b.type='submit';b.innerHTML='🔎';
    b.setAttribute('aria-label',isAr?'بحث':'Search');
    f.appendChild(i);f.appendChild(b);
    if(brand&&brand.nextSibling)inner.insertBefore(f,brand.nextSibling);
    else inner.appendChild(f);
  }
  if(document.readyState!=='loading')build();
  else document.addEventListener('DOMContentLoaded',build);
})();

